import webpush from 'npm:web-push'
import { createClient } from 'npm:@supabase/supabase-js@2'

const supabase = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)
webpush.setVapidDetails(
  Deno.env.get('VAPID_SUBJECT') || 'mailto:admin@example.com',
  Deno.env.get('VAPID_PUBLIC_KEY')!,
  Deno.env.get('VAPID_PRIVATE_KEY')!,
)

Deno.serve(async (req) => {
  try {
    const payload = await req.json()
    const job = payload.record || payload
    if (!job?.id || !job?.teacher_id) return new Response(JSON.stringify({ ok: false, error: 'invalid job' }), { status: 400 })
    let subscriptionsQuery = supabase.from('push_subscriptions').select('id,endpoint,p256dh,auth').eq('teacher_id', job.teacher_id)
    subscriptionsQuery = job.student_id ? subscriptionsQuery.eq('student_id', job.student_id) : subscriptionsQuery.is('student_id', null)
    const { data: subscriptions, error } = await subscriptionsQuery
    if (error) throw error
    const message = JSON.stringify({ title: job.title || 'النخبة', body: job.body || 'لديك تنبيه جديد', url: job.url || '/' })
    for (const subscription of subscriptions || []) {
      try {
        await webpush.sendNotification({ endpoint: subscription.endpoint, keys: { p256dh: subscription.p256dh, auth: subscription.auth } }, message)
      } catch (err) {
        if (err?.statusCode === 404 || err?.statusCode === 410) await supabase.from('push_subscriptions').delete().eq('id', subscription.id)
      }
    }
    await supabase.from('push_notification_jobs').update({ processed_at: new Date().toISOString() }).eq('id', job.id)
    return new Response(JSON.stringify({ ok: true, sent: subscriptions?.length || 0 }), { headers: { 'content-type': 'application/json' } })
  } catch (err) {
    console.error(err)
    return new Response(JSON.stringify({ ok: false, error: String(err?.message || err) }), { status: 500, headers: { 'content-type': 'application/json' } })
  }
})
